def read_data
  @content = read(@site.config["data_dir"])

  theme = @site.theme
  data_path = theme&.data_path
  if data_path
    theme_root = theme.root
    theme_data = self.class.new(
      @site,
      :in_source_dir => proc do |*paths|
        paths.reduce(theme_root) { |base, path| Jekyll.sanitized_path(base, path) }
      end
    ).read(data_path)
    @content = Jekyll::Utils.deep_merge_hashes(theme_data, @content)
  end

  @site.data = wrap_data(@content)
end

private

def wrap_data(data)
  return data if data.is_a?(DataEntry) || data.is_a?(DataHash)
  return data unless data.is_a?(Hash)

  wrapped = data.each_with_object({}) do |(key, value), hash|
    hash[key] = wrap_data(value)
  end
  DataHash.new(wrapped, @site)
end

def current_document=(document)
  @current_document = document
  site_data = @obj.site_data
  return unless site_data.respond_to?(:current_document=)

  site_data.current_document = document
