def document_path
  if current_document.is_a?(Jekyll::Page)
    return @site.in_source_dir(current_document.relative_path)
  end

  document = current_document.path

def read_data_to(dir, data)
  return unless File.directory?(dir) && !@entry_filter.symlink?(dir)

  data_entries(dir).each do |entry|
    read_data_entry(dir, data, entry)
  end
end

def data_entries(dir)
  Dir.chdir(dir) do
    Dir["*.{yaml,yml,json,csv,tsv}"] + Dir["*"].select { |fn| File.directory?(fn) }
  end
end

def read_data_entry(dir, data, entry)
  path = @in_source_dir.call(dir, entry)
  return if @entry_filter.symlink?(path)

  if File.directory?(path)
    read_data_to(path, data[sanitize_filename(entry)] = {})
  else
    key = sanitize_filename(File.basename(entry, ".*"))
    data[key] = DataEntry.new(read_data_file(path), path)
  end
end

